if(path==='/api/backend/v1/billing/usage'){reply({accountId,availableBalance:10000,reservedCredits:0,totalSpent:0,debtCredits:0,items:[],nextCursor:null});return;}
if(path===api+'/config'){reply({accountId,enabled:true,costMultiplier:3,models:GENERATION_MODELS.map(m=>({...m,supportsReferenceImage:m.id!=='google/veo-3.1-lite'}))});return;}
if(path===api+'/references'&&method==='POST'){counts.uploads++;const v=await body();if(failUpload){reply({error:'本地隔离：参考图上传失败，请重试。'},503);return;}const image=parseReferenceImage(v.dataUrl),id=crypto.randomUUID(),reference={id,name:v.name,mimeType:image.mime,byteLength:image.bytes.length,width:image.width,height:image.height,assetUrl:api+'/reference-assets/'+id};refs.set(id,{accountId,reference,bytes:image.bytes});reply({accountId,reference},201);return;}
if(path.startsWith(api+'/reference-assets/')||path.startsWith(api+'/references/')){const id=path.split('/').at(-1),v=refs.get(id);if(!v||v.accountId!==accountId||expireReference){reply({error:'参考图已移除或过期，请重新上传。',code:'generation_reference_missing'},404);return;}if(path.includes('/reference-assets/')){counts.referenceFileReads++;res.writeHead(200,{'Content-Type':v.reference.mimeType,'Cache-Control':'no-store'});res.end(v.bytes);return;}if(method==='DELETE'){refs.delete(id);reply({accountId,deleted:true});return;}reply({accountId,reference:v.reference});return;}
if(path===api+'/quote'){const v=await body();counts.quotes++;if(v.referenceImageId&&(!refs.has(v.referenceImageId)||expireReference)){reply({error:'参考图已移除或过期，请重新上传。',code:'generation_reference_missing'},404);return;}reply({accountId,quote:{estimatedCredits:v.kind==='image'?100:320,maxCredits:v.kind==='image'?120:384}});return;}
